#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <random>
#include <set>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
namespace fs=std::filesystem;
namespace {
void ensure(bool b,const std::string& message){if(!b)throw std::runtime_error(message);}
void save(const fs::path& p,const std::string& s){fs::create_directories(p.parent_path());std::ofstream o(p,std::ios::binary);ensure(bool(o),"cannot write "+p.string());o<<s;ensure(bool(o),"write failed");}
using Row=std::array<double,8>;
std::vector<Row> dataset(unsigned seed,unsigned count){std::mt19937 rng(seed);std::uniform_real_distribution<double> noise(-0.03,0.03);std::vector<Row> rows;rows.reserve(count);for(unsigned i=0;i<count;++i){Row r{};for(unsigned j=0;j<8;++j){double d=0.4+0.2*std::sin(i*0.051+j*.23)+noise(rng);if(i%73==0&&j==7)d+=0.3;r[j]=std::clamp(d,0.,1.);}rows.push_back(r);}return rows;}
double feature(const Row& r,int k){switch(k){case 0:return r[0];case 1:return r[7];case 2:{double s=0;for(double x:r)s+=x;return s/8.;}case 3:return *std::max_element(r.begin(),r.end());case 4:return *std::min_element(r.begin(),r.end());case 5:return std::abs(r[7]-r[0]);default:{double s=0;for(double x:r)s+=(x-.5)*(x-.5);return s/8.;}}}
struct Idea{int a=0,b=0,op=0;double complexity=0,variance=0,mae=0;};
double run(const Row& r,const Idea& i){const double a=feature(r,i.a),b=feature(r,i.b);switch(i.op){case 0:return (a+b)/2.;case 1:return std::abs(a-b);case 2:return std::max(a,b);case 3:return std::min(a,b);case 4:return a*b;default:return std::clamp(a-b+.5,0.,1.);}}
std::string name(const Idea& i){return "purpose_f"+std::to_string(i.a)+"_f"+std::to_string(i.b)+"_op"+std::to_string(i.op);}
void selftest(){Idea i{0,1,1};Row r{.1,.2,.3,.4,.5,.6,.7,.8};ensure(std::abs(run(r,i)-.7)<1e-12,"feature test");ensure(dataset(5,20).size()==20,"data test");std::cout<<"V14_PURPOSE_SELFTEST PASS\n";}
void emit(const fs::path& p,const Idea& idea){fs::create_directories(p);std::ostringstream h;h<<"#pragma once\n#include <algorithm>\n#include <array>\n#include <cmath>\nnamespace candidate {using Row=std::array<double,8>;\ninline double feature(const Row& r,int k){switch(k){case 0:return r[0];case 1:return r[7];case 2:{double s=0;for(double x:r)s+=x;return s/8.;}case 3:return *std::max_element(r.begin(),r.end());case 4:return *std::min_element(r.begin(),r.end());case 5:return std::abs(r[7]-r[0]);default:{double s=0;for(double x:r)s+=(x-.5)*(x-.5);return s/8.;}}}\ninline double evaluate(const Row& r){double a=feature(r,"<<idea.a<<"),b=feature(r,"<<idea.b<<");switch("<<idea.op<<"){case 0:return (a+b)/2.;case 1:return std::abs(a-b);case 2:return std::max(a,b);case 3:return std::min(a,b);case 4:return a*b;default:return std::clamp(a-b+.5,0.,1.);}}}\n";save(p/"candidate.hpp",h.str());
std::string main=R"CPP(#include "candidate.hpp"
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
int main(int argc,char** argv){try{if(argc==2&&std::string(argv[1])=="--selftest"){candidate::Row r{.1,.2,.3,.4,.5,.6,.7,.8};if(!std::isfinite(candidate::evaluate(r)))return 4;std::cout<<"SELFTEST PASS\n";return 0;}if(argc!=3){std::cerr<<"Usage: discovered_app INPUT.csv OUTPUT.csv\n";return 2;}std::ifstream in(argv[1]);if(!in)throw std::runtime_error("input unavailable");std::ofstream out(argv[2]);if(!out)throw std::runtime_error("output unavailable");out<<"row,value\n"<<std::setprecision(17);std::string line;unsigned count=0;while(std::getline(in,line)){if(line.empty())continue;candidate::Row r{};std::istringstream ss(line);std::string cell;for(double& x:r){if(!std::getline(ss,cell,','))throw std::runtime_error("malformed row");std::size_t consumed=0;x=std::stod(cell,&consumed);if(consumed!=cell.size()||!std::isfinite(x))throw std::runtime_error("non-numeric input");}if(std::getline(ss,cell,','))throw std::runtime_error("extra column");out<<count++<<','<<candidate::evaluate(r)<<'\n';}std::cout<<"PROCESSED "<<count<<" rows\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
)CPP";save(p/"main.cpp",main);
std::string cm="cmake_minimum_required(VERSION 3.21)\nproject(open_purpose_candidate LANGUAGES CXX)\nset(CMAKE_CXX_STANDARD 20)\nset(CMAKE_CXX_STANDARD_REQUIRED ON)\nadd_executable(discovered_app main.cpp)\nif(MSVC)\n target_compile_options(discovered_app PRIVATE /W4 /WX /permissive- /EHsc)\nelse()\n target_compile_options(discovered_app PRIVATE -Wall -Wextra -Wpedantic -Werror)\nendif()\nenable_testing()\nadd_test(NAME generated_selftest COMMAND discovered_app --selftest)\n";save(p/"CMakeLists.txt",cm);
auto rows=dataset(421,256);std::ostringstream csv;csv<<std::setprecision(17);for(const auto& r:rows){for(unsigned j=0;j<8;++j){if(j)csv<<',';csv<<r[j];}csv<<'\n';}save(p/"example_input.csv",csv.str());save(p/"IDEA.md","# Generated experimental purpose\n\nPurpose: "+name(idea)+"\n\nThis program computes an experimentally proposed numerical transformation. It is NOT a verified human use case or a mathematical novelty claim.\n\nHuman evaluation is required before claiming usability.\n");}
void discover(const fs::path& root,unsigned budget){ensure(budget>=5&&budget<=100000,"budget 5..100000");auto train=dataset(11,384),holdout=dataset(97,384);std::mt19937 rng(6007);std::set<std::string> seen;std::vector<Idea> selected;std::ostringstream history;history<<"name,train_variance,holdout_variance,reference_mae,complexity,decision\n";for(unsigned k=0;k<budget;++k){Idea i{static_cast<int>(rng()%7U),static_cast<int>(rng()%7U),static_cast<int>(rng()%6U)};auto id=name(i);if(!seen.insert(id).second)continue;double sum=0,sq=0,err=0;for(auto& r:train){const double y=run(r,i);sum+=y;sq+=y*y;err+=std::abs(y-feature(r,2));}i.variance=std::max(0.,sq/train.size()-(sum/train.size())*(sum/train.size()));i.mae=err/train.size();i.complexity=static_cast<double>(i.op==4||i.op==5?2:1);double hs=0,hq=0;for(auto& r:holdout){const double y=run(r,i);hs+=y;hq+=y*y;}const double hv=std::max(0.,hq/holdout.size()-std::pow(hs/holdout.size(),2));const bool interesting=i.variance>0.0001&&hv>0.0001&&std::abs(i.variance-hv)<.05;history<<id<<','<<i.variance<<','<<hv<<','<<i.mae<<','<<i.complexity<<','<<(interesting?"CANDIDATE":"REJECTED")<<'\n';if(interesting)selected.push_back(i);}std::stable_sort(selected.begin(),selected.end(),[](const Idea&a,const Idea&b){return a.variance>b.variance;});if(selected.size()>4)selected.resize(4);save(root/"purpose_search.csv",history.str());std::ostringstream catalogue;catalogue<<"purpose,source_features,operation,status\n";for(const auto&i:selected){emit(root/"applications"/name(i),i);catalogue<<name(i)<<','<<i.a<<'+'<<i.b<<','<<i.op<<",NEEDS_REAL_WORLD_VALIDATION\n";}save(root/"purpose_catalogue.csv",catalogue.str());save(root/"RESEARCH_REPORT.md","# Open Purpose Explorer\n\nBudget: "+std::to_string(budget)+"\nGenerated apps: "+std::to_string(selected.size())+"\n\nCandidate selection uses output variation across two synthetic distributions; this does not establish usefulness. A real-world task and consent-based usability study are required. No universal unrestricted software invention is claimed.\n");std::cout<<"PURPOSE_DISCOVERY_COMPLETE applications="<<selected.size()<<" output="<<root.string()<<'\n';}
void startStudy(const fs::path& root,const std::string& purpose){fs::create_directories(root);ensure(purpose.size()<100&&!purpose.empty(),"invalid purpose");save(root/"STUDY_PROTOCOL.md","# Human usability study\n\nApplication purpose: "+purpose+"\n\nProvide participants with the program and a suitable CSV dataset. Explain that participation is voluntary and feedback is collected locally.\n\nTasks:\n1. Start the program unassisted.\n2. Load the input CSV, process it and locate the output file.\n3. Explain whether the result is understandable and useful for a real task.\n4. Record completion, elapsed seconds, errors, subjective ease score (1-5), and an optional comment.\n\nDo not claim tested humans until actual consented participant records exist. No personal names or identifiers required.\n");save(root/"participant_feedback.csv","session,consented,completed,seconds,errors,ease_1_to_5,useful_1_to_5,comment\n");std::cout<<"STUDY_READY "<<root.string()<<'\n';}
struct Feedback{unsigned count=0,completed=0;double ease=0,useful=0;};
Feedback inspect(const fs::path& file){std::ifstream in(file);ensure(bool(in),"feedback file missing");std::string line;ensure(bool(std::getline(in,line)),"empty feedback");ensure(line=="session,consented,completed,seconds,errors,ease_1_to_5,useful_1_to_5,comment","bad feedback header");std::set<std::string> sessions;Feedback f;while(std::getline(in,line)){if(line.empty())continue;std::istringstream ss(line);std::array<std::string,8> v{};for(unsigned n=0;n<7;++n)ensure(bool(std::getline(ss,v[n],',')),"incomplete feedback row");std::getline(ss,v[7]);ensure(!v[0].empty()&&sessions.insert(v[0]).second,"duplicate/empty session");ensure(v[1]=="yes"||v[1]=="no","invalid consent");if(v[1]=="no")continue;ensure(v[2]=="yes"||v[2]=="no","invalid completion");const double secs=std::stod(v[3]);int errs=std::stoi(v[4]),ease=std::stoi(v[5]),useful=std::stoi(v[6]);ensure(std::isfinite(secs)&&secs>=0&&errs>=0&&ease>=1&&ease<=5&&useful>=1&&useful<=5,"invalid score");++f.count;if(v[2]=="yes")++f.completed;f.ease+=ease;f.useful+=useful;}return f;}
void analyze(const fs::path& root){auto f=inspect(root/"participant_feedback.csv");std::string verdict="NO_HUMAN_EVIDENCE";if(f.count>=5)verdict=(f.completed*5>=f.count*4&&f.ease/f.count>=4&&f.useful/f.count>=4)?"PRELIMINARY_USABILITY_SUPPORT":"REVISION_RECOMMENDED";else if(f.count>0)verdict="INSUFFICIENT_HUMAN_SAMPLE";std::ostringstream o;o<<"# Human study analysis\n\nConsenting participants: "<<f.count<<"\nCompleted: "<<f.completed<<"\nAverage ease: "<<(f.count?f.ease/f.count:0)<<"\nAverage perceived usefulness: "<<(f.count?f.useful/f.count:0)<<"\nVerdict: "<<verdict<<"\n\nThis is a convenience-sample evaluation, not population proof.\n";save(root/"HUMAN_STUDY_REPORT.md",o.str());std::cout<<"HUMAN_STUDY "<<verdict<<" participants="<<f.count<<'\n';}
}
int main(int argc,char**argv){try{if(argc==2&&std::string(argv[1])=="selftest"){selftest();return 0;}if(argc==4&&std::string(argv[1])=="discover"){discover(argv[2],static_cast<unsigned>(std::stoul(argv[3])));return 0;}if(argc==4&&std::string(argv[1])=="study-init"){startStudy(argv[2],argv[3]);return 0;}if(argc==3&&std::string(argv[1])=="study-analyze"){analyze(argv[2]);return 0;}std::cerr<<"Usage: math_open_purpose_v14 selftest | discover DIR BUDGET | study-init DIR PURPOSE | study-analyze DIR\n";return 2;}catch(const std::exception&e){std::cerr<<"V14_ERROR: "<<e.what()<<'\n';return 1;}}
